var i=`0563-manti`;var t=`world-0563`;var o=`UZ`;var a=`central-asia`;var l=4;var g=97;var s={en:`Manti`,ua:`Манти по-узбецьки`};var r={en:`A traditional dish from Uzbekistan, centered on all-purpose flour, chicken egg, ground lamb, yellow onion. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Узбекистан. Основні складники: пшеничне борошно універсальне, куряче яйце, фарш з ягнятини, жовта цибуля. Домашній варіант із кількостями продуктів за етапами приготування.`};var u=[{en:`Mix the dough ingredients, knead until smooth and elastic, then cover and rest for about 20 minutes.`,ua:`Змішайте складники тіста, вимісіть до гладкості й еластичності, накрийте та залиште приблизно на 20 хвилин.`,t:[`mixing`,`kneading`,`resting-dough`],m:20,i:[[`all-purpose-flour`,420,`g`],[`water`,200,`ml`],[`chicken-egg`,1,`pcs`],[`table-salt`,5,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:12,i:[[`ground-lamb`,550,`g`],[`yellow-onion`,340,`g`],[`ground-cumin`,5,`g`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Roll the rested dough thinly, cut rounds, place filling in the center and pinch each dumpling tightly closed.`,ua:`Тонко розкачайте відпочиле тісто, виріжте кружальця, викладіть начинку в центр і ретельно заліпіть краї кожного вареника чи пельменя.`,t:[`rolling-out-dough`,`pinching-dumplings`],m:24,i:[]},{en:`Arrange Uzbek manty in an oiled steamer with space between parcels and steam about 35–40 minutes until the meat filling is fully cooked.`,ua:`Викладіть узбецькі манти на змащені решітки пароварки з проміжками, готуйте 35–40 хвилин до повної готовності фаршу.`,t:[`steaming`],m:38,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`plain-yogurt`,200,`g`]]}];var d={slug:i,id:t,country:`UZ`,region:a,servings:4,minutes:97,title:s,text:r,steps:u};export{o as country,d as default,t as id,g as minutes,a as region,l as servings,i as slug,u as steps,r as text,s as title};